const MINIS=[["☕ Make a coffee","Prepare a coffee in the correct service sequence.",["Place cup","Add espresso","Add milk","Serve coffee"]],["📦 Stock rotation","Arrange the items from earliest expiry to latest.",["Expires 1 Dec","Expires 3 Dec","Expires 7 Dec","Expires 12 Dec"]],["🛍️ Pack an order","Complete an order without missing anything.",["Check order ticket","Pick items","Check quantity","Seal and label"]],["💳 Checkout","Process a payment in the correct order.",["Scan items","Confirm total","Verify payment","Issue receipt"]],["🧼 Clean a spill","Restore the customer area safely.",["Warn customers","Secure area","Clean spill","Check and reopen"]],["🥤 Prepare a drink","Assemble the drink in the correct order.",["Get clean cup","Add ice","Pour drink","Fit lid"]],["🏷️ Label new stock","Receive and label a delivery.",["Check delivery note","Inspect items","Apply price labels","Update inventory"]],["🎁 Wrap a gift","Prepare the gift for collection.",["Choose correct item","Check condition","Wrap gift","Attach order label"]],["💵 Reconcile cash","Complete the cash-check procedure.",["Count actual cash","Compare expected cash","Record discrepancy","Sign off"]],["🚚 Dispatch an order","Get the order ready for delivery.",["Verify order","Pack securely","Attach address label","Record dispatch"]]];
const finalOriginal=ROUNDS.pop();
for(let i=0;i<EXTRA.length;i++){const [title,situation,question,...answers]=EXTRA[i];ROUNDS.push({title,time:'Business day',npc:'Customer / event supervisor',face:['😟','🤔','😠','🙂'][i%4],dialogue:situation,situation,effect:[-1,20,8,1],tasks:Array.from({length:4},()=>Q(question,answers,'Best decision: '+answers[0]))});}
ROUNDS.push(finalOriginal);ROUNDS.forEach((r,i)=>{const m=600+Math.round(i*420/49);r.time=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');});
