 state(token){const [s,p]=this.get(token),now=this.clock();p.seen=now;this.advance(s);const b=s.booths[p.booth],r=p.results.length,phase=now>=s.end?'closed':r>=50&&!p.mini?'finished':'playing';const publicPlayer=x=>({id:x.id,name:x.name,avatar:x.avatar,color:x.color,hat:x.hat,booth:x.booth,role:x.role,x:x.x,y:x.y,online:now-x.seen<120000,score:x.score+x.miniScore,completed:x.results.length,miniCompleted:x.miniResults.length});let task=null,mini=null;if(phase==='playing'&&p.mini){const m=p.mini,def=EDATA.MINIS[m.index];mini={index:m.index,title:def[0],instruction:def[1],choices:m.order.map(i=>def[2][i]),done:m.order.map(i=>i<m.progress),progress:m.progress,mistakes:m.mistakes,deadline:m.deadline};}else if(phase==='playing'&&r<50){const q=EDATA.ROUNDS[r].tasks[p.role],a=p.attempts[r]||{wrong:[]};task={round:r,time:EDATA.ROUNDS[r].time,title:EDATA.ROUNDS[r].title,npc:EDATA.ROUNDS[r].npc,face:EDATA.ROUNDS[r].face,dialogue:EDATA.ROUNDS[r].dialogue,situation:EDATA.ROUNDS[r].situation,question:q.question,choices:this.order(p,r).map(i=>q.answers[i]),wrong:a.wrong,deadline:p.deadline};}return {session:s.id,phase,now,start:s.start,end:s.end,chatDisabled:!!s.chatDisabled,muted:!!p.muted,me:{...publicPlayer(p),results:p.results,miniResults:p.miniResults},players:s.players.map(publicPlayer),booths:s.booths.map(x=>({...x,name:EDATA.BOOTHS[x.index][0],icon:EDATA.BOOTHS[x.index][1],product:EDATA.BOOTHS[x.index][2]})),task,mini,lastFeedback:p.lastFeedback,chat:s.chat.filter(m=>m.channel==='all'||m.booth===p.booth).slice(-100),demo:this.demo};}
